mapper.select:
SELECT tenant_id::text AS tenant_id,integration_id,group_binding_id::text AS group_binding_id,
    enabled,extractor_agent_id::text AS extractor_agent_id,revision,updated_by_principal
FROM nw_group_memory_extraction_policies WHERE tenant_id::text=#{tenant} AND integration_id=#{integration}
    AND group_binding_id::text=#{group}

SELECT end_user_id FROM nw_group_memberships WHERE tenant_id::text=#{tenant}
  AND integration_id=#{integration} AND group_binding_id::text=#{group}
ORDER BY end_user_id

SELECT EXISTS(SELECT 1 FROM agent_runtime_memory_extraction_jobs WHERE tenant_id=#{source.tenantId}
    AND source_event_id=#{event} AND extractor_version=#{extractor} AND policy_version=#{policy}
    AND memory_type='group-hydrate' AND canonical_fact_key='source' AND source_target_kind='GROUP'
    AND source_target_id=#{source.groupBindingId} AND source_session_id=#{source.sessionId}
    AND integration_id=#{source.integrationId} AND group_binding_id=CAST(#{source.groupBindingId} AS bigint)
    AND end_user_id=#{source.authorEndUserId})

mapper.delete:
DELETE FROM nw_group_memory_extraction_pending WHERE tenant_id::text=#{source.tenantId}
    AND integration_id=#{source.integrationId} AND group_binding_id::text=#{source.groupBindingId}
    AND source_message_id=#{source.sourceMessageId} AND source_sequence=#{source.sourceSequence}
